package br.com.erp.pos;
import br.com.erp.auth.*;
import br.com.erp.inventory.StockService;
import br.com.erp.shared.Audit;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static br.com.erp.pos.PosCommercialContracts.*;
@Service
public class SuspensionService {
 private final JdbcTemplate db;private final BranchAccess access;private final CartPricing pricing;private final CashService cash;private final Audit audit;
 public SuspensionService(JdbcTemplate db,BranchAccess access,CartPricing pricing,CashService cash,Audit audit){this.db=db;this.access=access;this.pricing=pricing;this.cash=cash;this.audit=audit;}
 private ResponseStatusException error(HttpStatus s,String text){return new ResponseStatusException(s,text);}
 private void lock(Actor a){db.queryForObject("SELECT id FROM tenant WHERE id=? FOR UPDATE",UUID.class,a.tenantId());}
 private String note(String text){String n=text.trim();if(n.length()<5)throw error(HttpStatus.BAD_REQUEST,"Justificativa deve conter cinco caracteres.");return n;}
 @Transactional(readOnly=true) public Suspension get(Actor a,UUID id){var rows=db.query("SELECT s.*,u.name AS created_by_name FROM pos_suspension s JOIN app_user u ON u.tenant_id=s.tenant_id AND u.id=s.created_by WHERE s.tenant_id=? AND s.id=?",(r,i)->new Suspension(r.getObject("id",UUID.class),r.getObject("branch_id",UUID.class),r.getObject("original_session_id",UUID.class),r.getObject("last_session_id",UUID.class),r.getObject("created_by",UUID.class),r.getObject("updated_by",UUID.class),r.getString("status"),r.getLong("version"),r.getString("note"),r.getBigDecimal("gross_total"),r.getBigDecimal("discount_total"),r.getBigDecimal("total"),pricing.decode(r.getString("items_json")),r.getObject("created_at",OffsetDateTime.class),r.getObject("updated_at",OffsetDateTime.class),r.getObject("sale_id",UUID.class),r.getString("discard_note"),r.getString("created_by_name")),a.tenantId(),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Suspensão não encontrada.");var s=rows.getFirst();access.requireBranch(a,s.branchId());if(!s.createdBy().equals(a.userId())&&!pricing.has(a,"pos:supervise"))throw error(HttpStatus.NOT_FOUND,"Suspensão não encontrada.");return s;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object> list(Actor a,String status,int page,int size){String where=" WHERE s.tenant_id=? AND "+BranchAccess.predicate("s.branch_id")+" AND (?=TRUE OR s.created_by=?) AND (?='' OR s.status=?)";boolean manager=pricing.has(a,"pos:supervise");var ids=db.query("SELECT s.id FROM pos_suspension s"+where+" ORDER BY s.updated_at DESC,s.id LIMIT ? OFFSET ?",(r,i)->r.getObject(1,UUID.class),a.tenantId(),a.tenantId(),a.userId(),manager,a.userId(),status,status,size,(long)page*size);return Map.of("items",ids.stream().map(id->get(a,id)).toList(),"total",db.queryForObject("SELECT COUNT(*) FROM pos_suspension s"+where,Long.class,a.tenantId(),a.tenantId(),a.userId(),manager,a.userId(),status,status),"page",page,"size",size);}
 private UUID replay(Actor a,UUID request,UUID expected,String kind,String hash){var rows=db.query("SELECT suspension_id,kind,fingerprint FROM pos_suspension_command WHERE tenant_id=? AND request_id=?",(r,i)->new Object[]{r.getObject(1,UUID.class),r.getString(2),r.getString(3)},a.tenantId(),request);if(rows.isEmpty())return null;var row=rows.getFirst();if(expected!=null&&!expected.equals(row[0])||!kind.equals(row[1])||!hash.equals(row[2]))throw error(HttpStatus.CONFLICT,"Identificador de comando reutilizado com outros dados.");return (UUID)row[0];}
 private void command(Actor a,UUID request,UUID id,String kind,String hash){db.update("INSERT INTO pos_suspension_command(tenant_id,request_id,suspension_id,kind,fingerprint) VALUES(?,?,?,?,?)",a.tenantId(),request,id,kind,hash);}
 @Transactional public Suspension save(Actor a,UUID id,CartInput input){lock(a);pricing.require(a,"pos:suspend");var current=id==null?null:get(a,id);var session=cash.get(a,input.sessionId());pricing.owner(a,session);if(current!=null&&!current.branchId().equals(session.branchId()))throw error(HttpStatus.BAD_REQUEST,"Caixa de retomada deve pertencer à filial original.");String note=note(input.note()),kind=id==null?"CREATE":"UPDATE";var fields=new ArrayList<Object>(Arrays.asList("SUSPEND",kind,id,input.version(),a.userId(),input.sessionId(),note));for(var i:input.items())Collections.addAll(fields,i.productId(),i.quantity(),i.expectedUnitPrice(),CartPricing.discount(i));String hash=StockService.fingerprint(fields.toArray());UUID replay=replay(a,input.requestId(),id,kind,hash);if(replay!=null)return get(a,replay);
  if(!session.status().equals("OPEN"))throw error(HttpStatus.CONFLICT,"Salvar suspensão exige caixa aberto.");if(id==null&&input.version()!=null)throw error(HttpStatus.BAD_REQUEST,"Nova suspensão não recebe versão.");if(current!=null&&(!current.status().equals("SUSPENDED")||input.version()==null||current.version()!=input.version()))throw error(HttpStatus.CONFLICT,"Suspensão alterada ou encerrada.");var quote=pricing.quote(a,session.branchId(),input.items());var now=OffsetDateTime.now(ZoneOffset.UTC);UUID result=id==null?UUID.randomUUID():id;
  if(id==null)db.update("INSERT INTO pos_suspension(id,tenant_id,branch_id,original_session_id,last_session_id,created_by,updated_by,created_at,updated_at,note,items_json,cart_hash,gross_total,discount_total,total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",result,a.tenantId(),session.branchId(),session.id(),session.id(),a.userId(),a.userId(),now,now,note,pricing.encode(quote.items()),quote.hash(),quote.grossTotal(),quote.discountTotal(),quote.total());
  else db.update("UPDATE pos_suspension SET last_session_id=?,updated_by=?,updated_at=?,note=?,items_json=?,cart_hash=?,gross_total=?,discount_total=?,total=?,version=version+1 WHERE tenant_id=? AND id=?",session.id(),a.userId(),now,note,pricing.encode(quote.items()),quote.hash(),quote.grossTotal(),quote.discountTotal(),quote.total(),a.tenantId(),id);
  command(a,input.requestId(),result,kind,hash);audit.record(a,id==null?"POS_SUSPENDED":"POS_SUSPENSION_UPDATED",result);return get(a,result);
 }
 @Transactional public Suspension discard(Actor a,UUID id,DiscardInput input){lock(a);pricing.require(a,"pos:suspend");var current=get(a,id);String note=note(input.note()),hash=StockService.fingerprint("SUSPEND_DISCARD",id,input.version(),note,a.userId());UUID replay=replay(a,input.requestId(),id,"DISCARD",hash);if(replay!=null)return get(a,replay);if(!current.status().equals("SUSPENDED")||current.version()!=input.version())throw error(HttpStatus.CONFLICT,"Suspensão alterada ou encerrada.");db.update("UPDATE pos_suspension SET status='DISCARDED',version=version+1,discard_note=?,updated_by=?,updated_at=? WHERE tenant_id=? AND id=?",note,a.userId(),OffsetDateTime.now(ZoneOffset.UTC),a.tenantId(),id);command(a,input.requestId(),id,"DISCARD",hash);audit.record(a,"POS_SUSPENSION_DISCARDED",id);return get(a,id);}
 public void authorizeCheckout(Actor a,UUID id,Long version,UUID branch,CartPricing.Quote quote){if(id==null){if(version!=null)throw error(HttpStatus.BAD_REQUEST,"Versão de suspensão sem identidade.");return;}pricing.require(a,"pos:suspend");var s=get(a,id);String hash=db.queryForObject("SELECT cart_hash FROM pos_suspension WHERE tenant_id=? AND id=?",String.class,a.tenantId(),id);if(!s.status().equals("SUSPENDED")||version==null||s.version()!=version||!s.branchId().equals(branch)||!hash.equals(quote.hash()))throw error(HttpStatus.CONFLICT,"Suspensão alterada, encerrada ou carrinho diferente. Salve as alterações antes de concluir.");}
 public void complete(Actor a,UUID id,UUID session,UUID sale){if(id!=null){db.update("UPDATE pos_suspension SET status='COMPLETED',version=version+1,sale_id=?,last_session_id=?,updated_by=?,updated_at=? WHERE tenant_id=? AND id=?",sale,session,a.userId(),OffsetDateTime.now(ZoneOffset.UTC),a.tenantId(),id);audit.record(a,"POS_SUSPENSION_COMPLETED",id);}}
}
